        "<p class=\"editor-note\" id=\"editorNote\">设备确认写入后，才会显示保存成功。</p><button class=\"rebase\" type=\"button\" id=\"rebase\" hidden>保留我修改的字段，合并最新设置</button><p class=\"notice\" id=\"editorStatus\" role=\"status\" aria-live=\"polite\"></p><div class=\"actions\"><button type=\"button\" class=\"quiet\" id=\"verify\">刷新设备并核对</button><button type=\"submit\" class=\"primary\" id=\"save\">保存到时钟</button></div></form></dialog>\n"
        "<script>\n"
        "'use strict';\n"
        "const $=id=>document.getElementById(id),days=()=>Array.from(document.querySelectorAll('[data-day]'));\n"
        "const S={snapshot:null,draft:null,pending:false,loading:false,uncertain:false,status:{}};\n"
        "const pad=n=>String(Number(n)).padStart(2,'0'),escape=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n"
        "function notice(text,tone=''){for(const id of ['notice','editorStatus']){$(id).textContent=text;$(id).dataset.tone=tone;}}\n"
        "function stale(){return !!(S.draft&&S.snapshot&&(S.draft.session!==S.snapshot.session||S.draft.version!==S.snapshot.version));}\n"
        "function writable(){return S.snapshot&&!S.snapshot.local_editing&&!S.snapshot.saving&&!O.pending;}\n"
        "function lock(){const busy=S.pending||S.loading;$('refresh').disabled=busy;$('save').disabled=busy||S.uncertain||!writable()||stale();$('close').disabled=S.pending;$('verify').disabled=busy;$('rebase').disabled=busy||S.uncertain;for(const id of ['alarmTime','enabled','alarmDate','snooze','ring'])$(id).disabled=S.pending;for(const d of days())d.disabled=S.pending;for(const b of document.querySelectorAll('[data-edit],[data-toggle]'))b.disabled=busy||S.uncertain||!writable();$('rebase').hidden=!stale();if(typeof O!=='undefined')otaLock();}\n"
        "function repeat(a){if(!a.repeat_mask)return `${a.year}-${pad(a.month)}-${pad(a.day)} · 仅一次`;if(a.repeat_mask===127)return '每天';if(a.repeat_mask===31)return '周一至周五';if(a.repeat_mask===96)return '周末';return '每周 '+Array.from('一二三四五六日').filter((_,i)=>a.repeat_mask&(1<<i)).join(' / ');}\n"
        "function render(){const s=S.snapshot;if(!s)return;$('deviceTime').textContent=s.time_valid?s.time:'设备时间未校准';$('summary').textContent=s.local_editing?'设备正在本机编辑':s.saving?'设备正在写入':s.storage_ok?'8 个闹钟 · 已连接':'存储不可用';$('grid').innerHTML=s.alarms.map(a=>{const t=S.status[a.id]||{},disabled=S.pending||S.loading||S.uncertain||!writable();return `<article class=\"card ${a.enabled?'':'off'}\"><div class=\"card-head\"><span class=\"alarm-name\">ALARM ${pad(a.id)}</span><button class=\"switch\" role=\"switch\" aria-checked=\"${!!a.enabled}\" aria-label=\"${a.enabled?'关闭':'开启'}闹钟 ${Number(a.id)}\" data-toggle=\"${Number(a.id)}\" ${disabled?'disabled':''}><span></span></button></div><div class=\"alarm-time\">${pad(a.hour)}:${pad(a.minute)}</div><p class=\"repeat\">${escape(repeat(a))}${s.ringing_mask&(1<<(a.id-1))?' · 正在响铃':s.snoozed_mask&(1<<(a.id-1))?' · 稍后提醒中':''}</p><div class=\"card-bottom\"><span class=\"tags\">稍后 ${Number(a.snooze_seconds)/60} 分钟 · 响铃 ${Number(a.ring_seconds)} 秒</span><button class=\"edit\" data-edit=\"${Number(a.id)}\" ${disabled?'disabled':''}>编辑</button></div><p id=\"status${Number(a.id)}\" class=\"card-status\" data-tone=\"${escape(t.tone||'')}\" aria-live=\"polite\">${escape(t.text||'')}</p></article>`;}).join('');lock();}\n"
        "function cardStatus(id,text,tone=''){S.status[id]={text,tone};const e=$('status'+id);if(e){e.textContent=text;e.dataset.tone=tone;}}\n"
        "async function api(url,options){const control=new AbortController(),timer=setTimeout(()=>control.abort(),35000);try{const r=await fetch(url,{...options,signal:control.signal,cache:'no-store'}),body=await r.json();if(!r.ok){const e=new Error(body.error||'request');e.status=r.status;e.code=body.error;throw e;}return {body,status:r.status};}finally{clearTimeout(timer);}}\n"
        "function validSnapshot(s){return s&&Number.isInteger(s.session)&&Number.isInteger(s.version)&&Array.isArray(s.alarms)&&s.alarms.length===8&&s.alarms.every((a,i)=>a.id===i+1);}\n"
        "async function load(manual=false){if(S.loading)return false;S.loading=true;lock();try{const {body}=await api('/api/alarms');if(!validSnapshot(body))throw new Error('invalid snapshot');S.snapshot=body;if(body.ota_supported&&!O.supported){O.supported=true;loadOta();}else if(!body.ota_supported){$('otaVersion').textContent='独立应用';$('otaStatus').textContent='此固件未启用网页升级。';}if(manual)S.uncertain=false;render();if(manual)notice(S.draft?'已刷新设备数据，编辑草稿保持不变，请核对。':'已刷新设备数据。');else if(!S.draft&&!S.pending)notice(body.storage_ok?'已连接，可编辑闹钟。':'尚无已确认的存储记录，可尝试保存并等待设备确认。',body.storage_ok?'':'error');if(S.draft){const a=body.alarms.find(x=>x.id===S.draft.entry.id);$('editorNote').textContent='设备当前：'+pad(a.hour)+':'+pad(a.minute)+' · '+repeat(a)+' · '+(a.enabled?'开启':'关闭')+' · 稍后 '+a.snooze_seconds/60+' 分钟 · 响铃 '+a.ring_seconds+' 秒。'+(stale()?'设备数据已变化，草稿已保留。请核对后合并最新设置。':'草稿保持不变，请核对后再决定是否提交。');}return true;}catch(e){notice('连接失败，请确认手机与时钟在同一局域网后刷新。','error');return false;}finally{S.loading=false;lock();}}\n"
        "function dateChange(){$('dateBox').hidden=days().some(d=>d.checked);}\n"
        "function openEditor(id){if(!S.snapshot||S.pending||S.loading||S.uncertain)return;const a=S.snapshot.alarms.find(x=>x.id===id);if(!a)return;S.draft={entry:{...a},session:S.snapshot.session,version:S.snapshot.version};$('editorTitle').textContent='编辑闹钟 '+pad(id);$('alarmTime').value=pad(a.hour)+':'+pad(a.minute);$('enabled').checked=!!a.enabled;$('alarmDate').value=a.year+'-'+pad(a.month)+'-'+pad(a.day);$('snooze').value=String(a.snooze_seconds/60);$('ring').value=String(a.ring_seconds);for(const d of days())d.checked=!!(a.repeat_mask&(1<<Number(d.dataset.day)));$('editorNote').textContent='设备确认写入后，才会显示保存成功。';$('editorStatus').textContent='';dateChange();lock();$('editor').showModal();}\n"
        "function closeEditor(){if(S.pending)return;S.draft=null;$('editor').close();lock();}\n"
        "function fillEntry(a){$('alarmTime').value=pad(a.hour)+':'+pad(a.minute);$('enabled').checked=!!a.enabled;$('alarmDate').value=a.year+'-'+pad(a.month)+'-'+pad(a.day);$('snooze').value=String(a.snooze_seconds/60);$('ring').value=String(a.ring_seconds);for(const d of days())d.checked=!!(a.repeat_mask&(1<<Number(d.dataset.day)));dateChange();}\n"
        "function groupValue(a,keys){if(keys[0]==='hour')return pad(a.hour)+':'+pad(a.minute);if(keys[0]==='year')return a.year+'-'+pad(a.month)+'-'+pad(a.day);if(keys[0]==='repeat_mask')return repeat(a);if(keys[0]==='enabled')return a.enabled?'开启':'关闭';if(keys[0]==='snooze_seconds')return a.snooze_seconds/60+' 分钟';return a.ring_seconds+' 秒';}\n"
        "function rebaseDraft(){if(!S.draft||!S.snapshot||S.pending||S.loading||S.uncertain)return;let current;try{current=readEntry();}catch(e){notice(e.message,'error');return;}const base=S.draft.entry,latest=S.snapshot.alarms.find(a=>a.id===base.id),merged={...latest},conflicts=[],groups=[['时间',['hour','minute']],['日期',['year','month','day']],['重复',['repeat_mask']],['启用',['enabled']],['稍后提醒',['snooze_seconds']],['响铃时长',['ring_seconds']]];for(const [label,keys]of groups){const edited=keys.some(k=>current[k]!==base[k]);if(edited){for(const k of keys)merged[k]=current[k];if(keys.some(k=>latest[k]!==base[k])&&keys.some(k=>current[k]!==latest[k]))conflicts.push(label+'：草稿 '+groupValue(current,keys)+' / 设备 '+groupValue(latest,keys));}}fillEntry(merged);S.draft.entry={...latest};S.draft.session=S.snapshot.session;S.draft.version=S.snapshot.version;$('editorNote').textContent=conflicts.length?'已合并未修改的设置。'+conflicts.join('；')+'。保存将使用草稿中的这些字段，请核对。':'已合并最新设置，仅保留你修改的字段。请核对后保存。';lock();}\n"
        "function integer(value,min,max,label){if(!/^\\d+$/.test(value)||Number(value)<min||Number(value)>max)throw new Error(label+'超出有效范围。');return Number(value);}\n"
        "function readEntry(){const a={...S.draft.entry},time=$('alarmTime').value.match(/^(\\d{2}):(\\d{2})$/),date=$('alarmDate').value.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);if(!time||!date)throw new Error('请填写完整的时间和日期。');a.hour=integer(time[1],0,23,'小时');a.minute=integer(time[2],0,59,'分钟');a.year=integer(date[1],2020,2099,'年份');a.month=integer(date[2],1,12,'月份');a.day=integer(date[3],1,31,'日期');const check=new Date(Date.UTC(a.year,a.month-1,a.day));if(check.getUTCFullYear()!==a.year||check.getUTCMonth()!==a.month-1||check.getUTCDate()!==a.day)throw new Error('日期不存在，请重新选择。');a.enabled=$('enabled').checked;a.repeat_mask=days().reduce((m,d)=>m|(d.checked?1<<Number(d.dataset.day):0),0);a.snooze_seconds=integer($('snooze').value,1,30,'稍后提醒分钟数')*60;a.ring_seconds=integer($('ring').value,5,600,'响铃秒数');return a;}\n"
        "async function commit(a,session,version){if(S.pending||S.uncertain)return false;S.pending=true;lock();cardStatus(a.id,'正在提交…');notice('正在提交，请稍候…');let phase='post';try{const body=new URLSearchParams();for(const [key,value]of Object.entries({session,version,enabled:a.enabled?1:0,hour:a.hour,minute:a.minute,repeat_mask:a.repeat_mask,year:a.year,month:a.month,day:a.day,ring_seconds:a.ring_seconds,snooze_seconds:a.snooze_seconds}))body.set(key,String(value));const response=await api('/api/alarms/'+a.id,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Clock-Request':'1'},body:body.toString()});phase='result';const receipt=response.body;if(response.status!==202||!Number.isInteger(receipt.id)||receipt.id<1||receipt.id>4294967295||receipt.state!=='pending')throw new Error('invalid receipt');cardStatus(a.id,'设备正在写入…');notice('设备正在写入，请等待保存确认…');const deadline=Date.now()+90000;while(Date.now()<deadline){const {body:result}=await api('/api/result?id='+receipt.id+'&session='+session);if(result.session!==session||result.state==='unknown')throw new Error('unknown');if(result.state==='failed'){cardStatus(a.id,'保存失败，请检查设备后重试。','error');notice('保存失败，设备未确认写入。草稿已保留。','error');return false;}if(result.state==='saved'){phase='saved';if(!await load(false))throw new Error('refresh');if(S.draft&&S.draft.entry.id===a.id){S.draft=null;$('editor').close();}cardStatus(a.id,'已保存到时钟','success');notice('已保存到时钟，并刷新了设备数据。','success');return true;}if(result.state!=='pending')throw new Error('invalid result');await new Promise(resolve=>setTimeout(resolve,1200));}throw new Error('result timeout');}catch(e){if(phase==='post'&&e.status){const messages={version_changed:'设备数据已变化，草稿已保留。请核对最新版本。',session_changed:'设备已重启，草稿已保留。请核对最新版本。',busy_or_local_editing:'设备正忙或正在本机编辑，请稍后手动重试。',alarm_unavailable:'闹钟服务暂时不可用，请刷新后重试。',invalid_fields:'参数无效，请检查所有字段范围。',invalid_date:'日期不存在，请重新选择。',form_required:'提交格式不正确，请刷新页面后重试。',request_header_required:'请求校验失败，请刷新页面后重试。',conflict:'数据已被其他操作修改，草稿已保留。请核对最新版本。',busy:'设备正忙，请稍后手动重试。',local_editing:'设备正在本机编辑，请结束本机编辑后重试。',unavailable:'设备暂时不可用，请刷新后重试。',invalid:'参数无效，请检查时间、日期和范围。'};notice(messages[e.code]||'保存失败，请检查设备状态后重试。','error');cardStatus(a.id,'未保存，请检查提示。','error');if(['conflict','version_changed','session_changed'].includes(e.code))await load(false);}else{S.uncertain=true;const text=phase==='saved'?'设备已确认保存，但刷新失败。请刷新数据核对。':'保存结果暂不确定，请刷新数据核对，勿重复提交。';notice(text,'error');cardStatus(a.id,phase==='saved'?'设备已确认，待刷新核对。':'结果待核对，请刷新。','error');}return false;}finally{S.pending=false;lock();}}\n"
        "async function saveEditor(){if(!S.draft||S.pending||S.loading||S.uncertain)return;if(stale()){notice('请先核对最新数据，再选择保留草稿并使用最新版本。','error');return;}if(!writable()){notice('设备正在编辑或写入，请稍后重试。','error');return;}let a;try{a=readEntry();}catch(e){notice(e.message,'error');return;}await commit(a,S.draft.session,S.draft.version);}\n"
        "async function toggle(id){if(!S.snapshot||S.draft||S.pending||S.loading||S.uncertain)return;const prior=S.snapshot.alarms.find(a=>a.id===id);if(!prior)return;const desired=!prior.enabled;S.loading=true;lock();try{const {body}=await api('/api/alarms');if(!validSnapshot(body))throw new Error('snapshot');S.snapshot=body;render();if(!writable()){notice('设备正忙，请稍后重试。','error');return;}const a={...body.alarms.find(x=>x.id===id),enabled:desired};S.loading=false;await commit(a,body.session,body.version);}catch(e){notice('读取最新数据失败，未提交更改，请刷新后重试。','error');}finally{S.loading=false;lock();}}\n"
        "const O={pending:false,restarting:false,session:0,id:0,enabled:false,supported:false,loading:false};\n"
        "function otaLock(){$('otaStart').disabled=!O.enabled||O.pending||S.pending||S.loading||!!S.draft;$('otaToken').disabled=O.pending;}\n"
        "async function loadOta(){if(O.loading)return;O.loading=true;try{const {body:o}=await api('/api/ota');if(!Number.isInteger(o.session)||typeof o.enabled!=='boolean')throw new Error('invalid OTA status');const changed=O.session&&O.session!==o.session;O.session=o.session;O.enabled=o.enabled;const autoTexts={waiting:'等待联网',health:'等待设备健康确认',checking:'检查中',current:'已是最新',busy:'设备忙，结束编辑或提醒后自动重试',queued:'已排队，保存确认后将重启',unreachable:'后台不可达，本次开机最多检查三次',failed:'自动升级请求未保存，当前应用继续运行',blocked:'本次启动暂不自动升级，请检查当前升级状态'};$('otaAuto').textContent=o.autoEnabled?'开机自动检查：'+(autoTexts[o.autoState]||'等待检查'):'开机自动检查已关闭';$('otaVersion').textContent='当前固件版本：'+Number(o.version)+' · '+(o.identity||'独立应用');if(changed&&O.pending){O.pending=false;O.restarting=false;$('otaStatus').textContent='设备已重新连接，请核对当前实际固件版本。';await load(false);}else if(o.state==='saved'){O.pending=true;O.restarting=true;$('otaStatus').textContent='升级请求已保存，即将重启。设备会暂时离线，请等待重连后核对版本。';}else if(o.state==='queued'){O.pending=true;O.id=o.id;$('otaStatus').textContent='请求已排队，正在等待设备确认写入。';}else if(o.state==='failed'){O.pending=false;O.restarting=false;$('otaStatus').textContent='升级请求未保存（错误 '+Number(o.error)+'），当前应用继续运行，请检查设备后重试。';}else if(!O.pending){$('otaStatus').textContent=o.enabled?'设备已就绪。请先在电脑上启动固件服务器，再输入管理令牌。':'此固件未启用网页升级或尚未配置管理令牌。';}}catch(e){if(O.pending)$('otaStatus').textContent='设备暂时离线，可能正在重启或恢复下载。请查看电脑服务器与串口，等待重连后核对版本。';else $('otaStatus').textContent='暂时无法读取升级状态，请稍后刷新。';}finally{O.loading=false;otaLock();}}\n"
        "async function startOta(){if(O.pending||!O.enabled||S.pending||S.draft)return;const token=$('otaToken').value.trim();if(!/^[0-9a-fA-F]{64}$/.test(token)){$('otaStatus').textContent='请输入完整的 64 位十六进制管理令牌。';return;}if(!window.confirm('确认开始固件升级？设备会暂时离线；请确保电脑固件服务器已经启动。'))return;O.pending=true;otaLock();const body=new URLSearchParams({session:String(O.session),token});$('otaToken').value='';try{const result=await api('/api/ota',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Clock-Request':'1'},body:body.toString()});if(result.status!==202||!Number.isInteger(result.body.id))throw new Error('invalid OTA receipt');O.id=result.body.id;$('otaStatus').textContent='请求已排队，正在等待设备确认写入。';await loadOta();}catch(e){if(e.status){O.pending=false;const messages={403:'会话或管理令牌无效，请刷新后重新输入。',409:'设备正在保存、编辑或提醒，请结束操作后重试。',503:'此设备暂不可进行网页升级。'};$('otaStatus').textContent=messages[e.status]||'请求失败，请刷新设备状态。';}else{$('otaStatus').textContent='请求结果暂不确定，正在查询设备状态，请勿重复提交。';await loadOta();}}finally{otaLock();}}\n"
        "$('otaStart').addEventListener('click',startOta);setInterval(()=>{if(O.supported&&O.pending)loadOta();},1500);setInterval(()=>{if(O.supported&&!O.pending)loadOta();},10000);\n"
        "$('refresh').addEventListener('click',()=>load(true));$('verify').addEventListener('click',()=>load(true));$('form').addEventListener('submit',e=>{e.preventDefault();saveEditor();});$('close').addEventListener('click',closeEditor);$('rebase').addEventListener('click',rebaseDraft);$('editor').addEventListener('cancel',e=>{if(S.pending)e.preventDefault();else S.draft=null;});for(const d of days())d.addEventListener('change',dateChange);$('grid').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.edit)openEditor(Number(b.dataset.edit));else if(b.dataset.toggle)toggle(Number(b.dataset.toggle));});setInterval(()=>{if(!S.draft&&!S.pending&&!S.loading&&!S.uncertain)load(false);},10000);load(false);\n"
        "</script></body></html>\n";
const size_t clock_web_page_length = sizeof(clock_web_page) - 1u;
